usuarios = [
    {"_id": i, "email": f"user{i}@test.com"} for i in range(1, 6)
]

def collection_scan(coleccion, campo, valor):
    pasos = 0
    for d in coleccion:
        pasos += 1
        if d[campo] == valor:
            return d, pasos
    return None, pasos

def crear_indice(coleccion, campo):
    return {d[campo]: d for d in coleccion}

def buscar_con_indice(indice, valor):
    return indice.get(valor), 1

objetivo = "user4@test.com"

doc_sin_indice, pasos_sin_indice = collection_scan(usuarios, "email", objetivo)
print(f"sin indice: {pasos_sin_indice} pasos, encontrado={doc_sin_indice is not None}")

indice_email = crear_indice(usuarios, "email")
doc_con_indice, pasos_con_indice = buscar_con_indice(indice_email, objetivo)
print(f"con indice: {pasos_con_indice} pasos, encontrado={doc_con_indice is not None}")
